p=argparse.ArgumentParser();p.add_argument('mode',choices=['begin','snapshot','close'],default='snapshot',nargs='?');a=p.parse_args();c=json.loads((OUT/'coordination.json').read_text());now=time.time();segments=c['owner_segments']
if not segments:segments.append({'start':c['program_start_epoch'],'end':None})
elif a.mode=='begin' and segments[-1].get('end') is not None:segments.append({'start':now,'end':None})
if a.mode=='close' and segments[-1].get('end') is None:segments[-1]['end']=now
c['root_owner_active']=segments[-1].get('end') is None;c['resource_ledger']='runs/a55_long_iteration_v1/resource_ledger.json';(OUT/'coordination.json').write_text(json.dumps(c,indent=2)+'\n')
