 k=str(z.get('model_pid',z.get('pid')));old=by.get(k,[0.,0.]);cpu=z.get('process_CPU_seconds',z.get('CPU_seconds',0));gpu=z.get('full_process_wall_seconds',0) if z.get('GPU_job') else z.get('GPU_job_wall_seconds',0);by[k]=[max(old[0],cpu),max(old[1],gpu)]
